// Tail latency: the average hides slow requests, and fan-out amplifies them.
const samples = [];
for (let i = 0; i < 98; i++) samples.push(50);   // 98 fast requests
samples.push(2000, 3000);                        // 2 very slow ones
samples.sort((a, b) => a - b);

function percentile(sorted, p) {
  // nearest-rank method: smallest value covering p percent of samples
  const rank = Math.ceil((p / 100) * sorted.length);
  return sorted[rank - 1];
}
const mean = samples.reduce((a, b) => a + b, 0) / samples.length;
console.log("samples: 98 x 50 ms, 1 x 2000 ms, 1 x 3000 ms");
console.log("mean = " + mean.toFixed(1) + " ms (nobody actually sees this)");
console.log("p50  = " + percentile(samples, 50) + " ms");
console.log("p99  = " + percentile(samples, 99) + " ms");

// Fan-out: a page needs n calls, each slow 1% of the time.
for (const n of [1, 10, 100]) {
  const pSlow = 1 - Math.pow(0.99, n);
  console.log("fan-out " + n + ": page is slow " + (pSlow * 100).toFixed(1) + "% of the time");
}
